sysauto_script.script:
// MidPulse — Mid Server Health & Queue Monitor — Scheduled Health Sweep
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function () {
    var collector = new MidPulseCollector();
    var analyzer = new MidPulseAnalyzer();
    var sweep = collector.sweepAll();
    var result = analyzer.analyze(sweep);
    gs.info("MidPulse sweep complete: health=" + result.global_health +
            ", agents=" + result.agent_count +
            ", snapshots=" + result.snapshots_written +
            ", alert=" + result.alert_fired);
})();
